def L(*rows):
    """Label rows 'TITLE|line|picture'."""
    return [tuple(r.split('|')) for r in rows]

def R(*rows):
    """Room rows 'NAME|picture'."""
    return [tuple(r.split('|')) for r in rows]

def C(*rows):
    """Card rows 'TITLE|picture|caption'."""
    return [tuple(r.split('|')) for r in rows]

def P(*rows):
    """Poster label rows 'HEADING|line'."""
    return [tuple(r.split('|')) for r in rows]

